 void talk(const StableId& actor,const StableId& provider){is.interactions.clear();InteractionSession session;session.id="meeting:"+actor;session.actor_id=actor;session.dialogue_id=provider+".dialogue";session.node_id="employment";session.phase="say";session.context.place_id="town";session.context.provider_actor_id=provider;session.context.role_id=provider+".role";is.interactions.push_back(session);}
 EstateEmploymentReceipt command(const StableId& actor,const EstateEmploymentCommand& command){auto result=apply_estate_employment(common,es,le,state,context(),meetings(),actor,command);if(!result.ok){std::cerr<<result.error.original.code<<" "<<result.error.original.path<<"\n";std::abort();}return result.value;}
 StableId employ(){talk("owner","worker");const auto offered=command("owner",EstateEmploymentOffer{"labor","worker"});talk("worker","owner");command("worker",EstateEmploymentDecision{offered.contract_id,"accept"});is.interactions.clear();return offered.contract_id;}
 void step(){DynamicStepInput input{common.tick(),common.tick()+1,{},{},{}};auto x=context(&input);OrganizationAccess org(common,os,oc,le);auto economic=step_local_economy(common,le,lc,org,activity,input,nullptr,nullptr,nullptr,&x);assert(economic.ok);auto estate=step_estate(common,es,ec,*cc,activity,input.to_tick);assert(estate.ok);auto worked=step_estate_employment(common,es,le,state,x,input);if(!worked.ok){std::cerr<<worked.error.original.code<<" "<<worked.error.original.path<<"\n";std::abort();}common.state().identity.tick=input.to_tick;assert(validate_estate(common,es,ec,*cc).ok);assert(validate_estate_employment(context()).ok);auto cold=validate_local_economy(common,le,lc,org,nullptr,nullptr,nullptr,&context_ref());assert(cold.ok);}
